// Services/Purchases/StoreManager.swift

import StoreKit

actor StoreManager {

    private let productIDs = ["com.app.auraPlus"]
    private var transactionsListenerTask: Task<Void, Never>?

    func purchaseAuraPlus() async throws -> EntitlementSnapshot {
        let products = try await Product.products(for: productIDs)
        guard let product = products.first else { throw NSError(domain: "Product not found", code: 0) }

        let result = try await product.purchase()
        switch result {
        case .success(let verification):
            let transaction = try checkVerified(verification)
            await transaction.finish()
            return EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date())
        case .userCancelled, .pending:
            throw NSError(domain: "Purchase cancelled or pending", code: 0)
        @unknown default:
            throw NSError(domain: "Unknown error", code: 0)
        }
    }

    func restorePurchases() async throws -> EntitlementSnapshot? {
        try await AppStore.sync()
        for await result in Transaction.updates {
            guard case .verified(let transaction) = result else { continue }
            if transaction.productID == productIDs.first {
                await transaction.finish()
                return EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date())
            }
        }
        return nil
    }

    private func checkVerified<T>(_ result: VerificationResult<T>) throws -> T {
        switch result {
        case .unverified(_, let error): throw error
        case .verified(let safe): return safe
        }
    }

    func startEntitlementListener(onChange: @escaping @Sendable (EntitlementSnapshot) -> Void) {
        transactionsListenerTask = Task.detached {
            for await update in Transaction.updates {
                guard case .verified(let transaction) = update else { continue }
                if transaction.productID == productIDs.first {
                    onChange(EntitlementSnapshot(isAuraPlus: true, unlockedPaletteTier: .auraPlusExpanded, capturedAt: Date()))
                }
            }
        }
    }
}
```

